Mesh<Point, double> faces;
std::map<Cell_handle, std::vector<Point>> cell_polygons;

// Iterate over all cells
for (auto it = rt.finite_cells_begin(); it != rt.finite_cells_end(); ++it) {
    // For each cell, we need to find its vertices and construct the power diagram face
    // In a regular triangulation, each cell has a dual power diagram face
}

// Actually, for power diagrams, we typically iterate over edges and find the dual faces
// Each edge in the triangulation corresponds to a face in the power diagram

for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    // Get the edge
    Cell_handle cell = it->first;
    int index = it->second;

    // Get the two vertices of the edge
    Vertex_handle v1 = cell->vertex(rt.vertex_triple_index(index, 0));
    Vertex_handle v2 = cell->vertex(rt.vertex_triple_index(index, 1));

    // The power diagram face is dual to this edge
    // We need to collect the cells incident to this edge and form a polygon
    std::vector<Point> polygon;

    // Get all cells incident to this edge
    std::vector<Cell_handle> incident_cells;
    rt.incident_cells(*it, std::back_inserter(incident_cells));

    // For each incident cell, get its vertex and construct the polygon
    for (auto cell_it = incident_cells.begin(); cell_it != incident_cells.end(); ++cell_it) {
        Cell_handle c = *cell_it;
        // Get the vertices of this cell
        for (int i = 0; i < 4; ++i) {
            polygon.push_back(c->vertex(i)->point());
        }
    }

    // Add the polygon to the mesh
    faces.add_face(polygon);
}

return faces;

